import { z } from "zod";
import { MarkDownContent } from "../other.mjs";
const zInfoIconProps = z.object({
    content: z.instanceof(MarkDownContent).or(z.string()),
    icon: z.string().optional(),
});
export function InfoIcon(define) {
    return define("InfoIcon")
        .props(zInfoIconProps)
        .render((props) => ({
        id: props.id,
        content: props.content,
        icon: props.icon,
    }));
}
